/* global describe, it, spyOn, MessageBus, expect, jasmine, testMB */

function approxEqual(valueOne, valueTwo) {
  return Math.abs(valueOne - valueTwo) < 500;
}

describe("Messagebus", function () {
  it("submits change requests", function(done){
    spyOn(this.MockedXMLHttpRequest.prototype, 'send').and.callThrough();
    var spec = this;
    MessageBus.subscribe('/test', function(){
      expect(spec.MockedXMLHttpRequest.prototype.send)
        .toHaveBeenCalled()
      var data = spec.MockedXMLHttpRequest.prototype.send.calls.argsFor(0)[0];
      var params = new URLSearchParams(data);
      expect(params.get("/test")).toEqual("-1");
      expect(params.get("__seq")).toMatch(/\d+/);
      done();
    });
  });

  it("calls callbacks", function(done){
    MessageBus.subscribe('/test', function(message){
      expect(message.password).toEqual('MessageBusRocks!');
      done();
    });
  });

  it('returns status', function(done){
    MessageBus.pause();
    expect(MessageBus.status()).toMatch("paused");
    MessageBus.resume();
    expect(MessageBus.status()).toMatch("started");
    MessageBus.stop();
    expect(MessageBus.status()).toMatch("stopped");
    done();
  });

  it('stores messages when paused, then delivers them when resumed', function(done){
    MessageBus.pause()
    spyOn(this.MockedXMLHttpRequest.prototype, 'send').and.callThrough();
    var spec = this;
    var onMessageSpy = jasmine.createSpy('onMessageSpy');
    MessageBus.subscribe('/test', onMessageSpy);
    setTimeout(function(){
      expect(spec.MockedXMLHttpRequest.prototype.send).toHaveBeenCalled()
      expect(onMessageSpy).not.toHaveBeenCalled()
      MessageBus.resume()
    }, 1010) // greater than delayPollTimeout of 500 + 500 random
    setTimeout(function(){
      expect(onMessageSpy).toHaveBeenCalled()
      done()
    }, 1050) // greater than first timeout above
  });

  it('can unsubscribe from callbacks', function(done){
    var onMessageSpy = jasmine.createSpy('onMessageSpy');
    MessageBus.subscribe('/test', onMessageSpy);
    MessageBus.unsubscribe('/test', onMessageSpy);
    MessageBus.subscribe('/test', function(){
      expect(onMessageSpy).not.toHaveBeenCalled()
      done()
    });
  });

  testMB('sets dlp parameter when longPolling is disabled', function(){
    MessageBus.enableLongPolling = false
    this.perform(function(message, xhr){
      expect(xhr.url).toMatch("dlp=t");
    }).finally(function(){
      MessageBus.enableLongPolling = true
    })
  });

  testMB('respects baseUrl setting', function(){
    MessageBus.baseUrl = "/a/test/base/url/";
    this.perform(function(message, xhr){
      expect(xhr.url).toMatch("/a/test/base/url/");
    }).finally(function(){
      MessageBus.baseUrl = "/";
    })
  });

  it('respects minPollInterval setting with defaults', function(){
    expect(MessageBus.minPollInterval).toEqual(100);
    MessageBus.minPollInterval = 1000;
    expect(MessageBus.minPollInterval).toEqual(1000);
  });

  testMB('sends using custom header', function(){
    MessageBus.headers['X-MB-TEST-VALUE'] = '42';
    this.perform(function(message, xhr){
      expect(xhr.headers).toEqual({
        'X-SILENCE-LOGGER': 'true',
        'X-MB-TEST-VALUE': '42',
        'Content-Type': 'application/x-www-form-urlencoded'
      });
    }).finally(function(){
      MessageBus.headers = {};
    })
  });

  it("respects Retry-After response header when larger than 15 seconds", async function () {
    spyOn(this.MockedXMLHttpRequest.prototype, "send").and.callThrough();
    spyOn(window, "setTimeout").and.callThrough();

    this.responseStatus = 429;
    this.responseHeaders["Retry-After"] = "23";

    await new Promise((resolve) => MessageBus.subscribe("/test", resolve));

    const nextPollScheduledIn = window.setTimeout.calls.mostRecent().args[1];
    expect(nextPollScheduledIn).toEqual(23000);
  });

  it("retries after 15s for lower retry-after values", async function () {
    spyOn(this.MockedXMLHttpRequest.prototype, "send").and.callThrough();
    spyOn(window, "setTimeout").and.callThrough();

    this.responseStatus = 429;
    this.responseHeaders["Retry-After"] = "13";

    await new Promise((resolve) => MessageBus.subscribe("/test", resolve));

    const nextPollScheduledIn = window.setTimeout.calls.mostRecent().args[1];
    expect(nextPollScheduledIn).toEqual(15000);
  });

  it("waits for callbackInterval after receiving data in chunked long-poll mode", async function () {
    // The callbackInterval is equal to the length of the server response in chunked long-poll mode, so
    // this ultimately ends up being a continuous stream of requests

    spyOn(this.MockedXMLHttpRequest.prototype, "send").and.callThrough();
    spyOn(window, "setTimeout").and.callThrough();

    await new Promise((resolve) => MessageBus.subscribe("/test", resolve));

    const nextPollScheduledIn = window.setTimeout.calls.mostRecent().args[1];
    expect(
      approxEqual(nextPollScheduledIn, MessageBus.callbackInterval)
    ).toEqual(true);
  });

  it("waits for backgroundCallbackInterval after receiving data in non-long-poll mode", async function () {
    spyOn(this.MockedXMLHttpRequest.prototype, "send").and.callThrough();
    spyOn(window, "setTimeout").and.callThrough();
    MessageBus.shouldLongPollCallback = () => false;
    MessageBus.enableChunkedEncoding = false;

    await new Promise((resolve) => MessageBus.subscribe("/test", resolve));

    const nextPollScheduledIn = window.setTimeout.calls.mostRecent().args[1];
    expect(
      approxEqual(nextPollScheduledIn, MessageBus.backgroundCallbackInterval)
    ).toEqual(true);
  });

  it("re-polls immediately after receiving data in non-chunked long-poll mode", async function () {
    spyOn(this.MockedXMLHttpRequest.prototype, "send").and.callThrough();
    spyOn(window, "setTimeout").and.callThrough();
    MessageBus.enableChunkedEncoding = false;

    await new Promise((resolve) => MessageBus.subscribe("/test", resolve));

    const nextPollScheduledIn = window.setTimeout.calls.mostRecent().args[1];
    expect(nextPollScheduledIn).toEqual(MessageBus.minPollInterval);
  });

  it("enters don't-chunk-mode if first chunk times out", async function () {
    spyOn(this.MockedXMLHttpRequest.prototype, "send").and.callThrough();
    spyOn(
      this.MockedXMLHttpRequest.prototype,
      "setRequestHeader"
    ).and.callThrough();

    let resolveFirstResponse;
    this.delayResponsePromise = new Promise(
      (resolve) => (resolveFirstResponse = resolve)
    );
    MessageBus.firstChunkTimeout = 50;

    await new Promise((resolve) => MessageBus.subscribe("/test", resolve));
    resolveFirstResponse();

    const calls =
      this.MockedXMLHttpRequest.prototype.setRequestHeader.calls.all();

    const dontChunkCalls = calls.filter((c) => c.args[0] === "Dont-Chunk");
    expect(dontChunkCalls.length).toEqual(1);
  });

  it("doesn't enter don't-chunk-mode if aborted before first chunk", async function () {
    spyOn(
      this.MockedXMLHttpRequest.prototype,
      "setRequestHeader"
    ).and.callThrough();

    this.delayResponsePromise = new Promise(() => {});
    MessageBus.firstChunkTimeout = 300;

    const requestWasStarted = new Promise(
      (resolve) => (this.requestStarted = resolve)
    );

    // Trigger request
    const subscribedPromise = new Promise((resolve) =>
      MessageBus.subscribe("/test", resolve)
    );

    await requestWasStarted;

    // Change subscription (triggers an abort and re-poll)
    MessageBus.subscribe("/test2", () => {});

    // Wait for stuff to settle
    await subscribedPromise;

    // Wait 300ms to ensure dontChunk timeout has passed
    await new Promise((resolve) => setTimeout(resolve, 300));

    const calls =
      this.MockedXMLHttpRequest.prototype.setRequestHeader.calls.all();

    const dontChunkCalls = calls.filter((c) => c.args[0] === "Dont-Chunk");
    expect(dontChunkCalls.length).toEqual(0);
  });
});

# frozen_string_literal: true

require_relative '../spec_helper'
require 'message_bus'

describe MessageBus do
  before do
    @bus = MessageBus::Instance.new
    @bus.site_id_lookup do
      "magic"
    end
    @bus.configure(test_config_for_backend(CURRENT_BACKEND))
  end

  after do
    @bus.reset!
    @bus.destroy
  end

  it "destroying immediately after `after_fork` does not lock" do
    10.times do
      @bus.on
      @bus.after_fork
      @bus.destroy
    end
  end

  describe "#base_route=" do
    it "adds leading and trailing slashes" do
      @bus.base_route = "my/base/route"
      @bus.base_route.must_equal '/my/base/route/'
    end

    it "leaves existing leading and trailing slashes" do
      @bus.base_route = "/my/base/route/"
      @bus.base_route.must_equal '/my/base/route/'
    end

    it "removes duplicate slashes" do
      @bus.base_route = "//my///base/route"
      @bus.base_route.must_equal '/my/base/route/'
    end
  end

  it "can subscribe from a point in time" do
    @bus.publish("/minion", "banana")

    data1 = []
    data2 = []
    data3 = []

    @bus.subscribe("/minion") do |msg|
      data1 << msg.data
    end

    @bus.subscribe("/minion", 0) do |msg|
      data2 << msg.data
    end

    @bus.subscribe("/minion", 1) do |msg|
      data3 << msg.data
    end

    @bus.publish("/minion", "bananana")
    @bus.publish("/minion", "it's so fluffy")

    wait_for(2000) do
      data3.length == 3 && data2.length == 3 && data1.length == 2
    end

    data1.must_equal ['bananana', "it's so fluffy"]
    data2.must_equal ['banana', 'bananana', "it's so fluffy"]
    data3.must_equal ['banana', 'bananana', "it's so fluffy"]
  end

  it "can transmit client_ids" do
    client_ids = nil

    @bus.subscribe("/chuck") do |msg|
      client_ids = msg.client_ids
    end

    @bus.publish("/chuck", { yeager: true }, client_ids: ['a', 'b'])
    wait_for(2000) { client_ids }

    client_ids.must_equal ['a', 'b']
  end

  it "should recover from a reset" do
    data = nil
    @bus.subscribe("/chuck") do |msg|
      data = msg.data
    end
    @bus.publish("/chuck", norris: true)
    @bus.publish("/chuck", norris: true)
    @bus.publish("/chuck", norris: true)

    @bus.backend_instance.reset!

    @bus.publish("/chuck", yeager: true)

    wait_for(2000) { data && data["yeager"] }

    data["yeager"].must_equal true
  end

  it "should recover from a backlog expiring" do
    data = nil
    @bus.subscribe("/chuck") do |msg|
      data = msg.data
    end
    @bus.publish("/chuck", norris: true)
    @bus.publish("/chuck", norris: true)
    @bus.publish("/chuck", norris: true)

    @bus.backend_instance.expire_all_backlogs!

    @bus.publish("/chuck", yeager: true)

    wait_for(2000) { data && data["yeager"] }

    data["yeager"].must_equal true
  end

  it "should automatically decode hashed messages" do
    data = nil
    @bus.subscribe("/chuck") do |msg|
      data = msg.data
    end
    @bus.publish("/chuck", norris: true)
    wait_for(2000) { data }

    data["norris"].must_equal true
  end

  it "should get a message if it subscribes to it" do
    user_ids, data, site_id, channel = nil

    @bus.subscribe("/chuck") do |msg|
      data = msg.data
      site_id = msg.site_id
      channel = msg.channel
      user_ids = msg.user_ids
    end

    @bus.publish("/chuck", "norris", user_ids: [1, 2, 3])

    wait_for(2000) { data }

    data.must_equal 'norris'
    site_id.must_equal 'magic'
    channel.must_equal '/chuck'
    user_ids.to_a.must_equal [1, 2, 3]
  end

  it "should get global messages if it subscribes to them" do
    data, site_id, channel = nil

    @bus.subscribe do |msg|
      data = msg.data
      site_id = msg.site_id
      channel = msg.channel
    end

    @bus.publish("/chuck", "norris")

    wait_for(2000) { data }

    data.must_equal 'norris'
    site_id.must_equal 'magic'
    channel.must_equal '/chuck'
  end

  it "should have the ability to grab the backlog messages in the correct order" do
    id = @bus.publish("/chuck", "norris")
    @bus.publish("/chuck", "foo")
    @bus.publish("/chuck", "bar")

    r = @bus.backlog("/chuck", id)

    r.map { |i| i.data }.to_a.must_equal ['foo', 'bar']
  end

  it "should correctly get full backlog of a channel" do
    @bus.publish("/chuck", "norris")
    @bus.publish("/chuck", "foo")
    @bus.publish("/chuckles", "bar")

    @bus.backlog("/chuck").map { |i| i.data }.to_a.must_equal ['norris', 'foo']
  end

  it "should correctly restrict the backlog size of a channel" do
    @bus.publish("/chuck", "norris")
    @bus.publish("/chuck", "foo", max_backlog_size: 1)

    @bus.backlog("/chuck").map { |i| i.data }.to_a.must_equal ['foo']
  end

  it "can be turned off" do
    @bus.off

    @bus.off?.must_equal true

    @bus.publish("/chuck", "norris")

    @bus.backlog("/chuck").to_a.must_equal []
  end

  it "can be turned off only for subscriptions" do
    @bus.off(disable_publish: false)

    @bus.off?.must_equal true

    data = []

    @bus.subscribe("/chuck") do |msg|
      data << msg.data
    end

    @bus.publish("/chuck", "norris")

    @bus.on

    @bus.subscribe("/chuck") do |msg|
      data << msg.data
    end

    @bus.publish("/chuck", "berry")

    wait_for(2000) { data.length > 0 }

    data.must_equal ["berry"]

    @bus.backlog("/chuck").map(&:data).to_a.must_equal ["norris", "berry"]
  end

  it "can call destroy multiple times" do
    @bus.destroy
    @bus.destroy
    @bus.destroy
  end

  it "can be turned on after destroy" do
    @bus.destroy

    @bus.on

    @bus.after_fork
  end

  it "allows you to look up last_message" do
    @bus.publish("/bob", "dylan")
    @bus.publish("/bob", "marley")
    @bus.last_message("/bob").data.must_equal "marley"
    assert_nil @bus.last_message("/nothing")
  end

  describe "#publish" do
    it "allows publishing to a explicit site" do
      data, site_id, channel = nil

      @bus.subscribe do |msg|
        data = msg.data
        site_id = msg.site_id
        channel = msg.channel
      end

      @bus.publish("/chuck", "norris", site_id: "law-and-order")

      wait_for(2000) { data }

      data.must_equal 'norris'
      site_id.must_equal 'law-and-order'
      channel.must_equal '/chuck'
    end
  end

  describe "global subscriptions" do
    before do
      seq = 0
      @bus.site_id_lookup do
        (seq += 1).to_s
      end
    end

    it "can get last_message" do
      @bus.publish("/global/test", "test")
      @bus.last_message("/global/test").data.must_equal "test"
    end

    it "can subscribe globally" do
      data = nil
      @bus.subscribe do |message|
        data = message.data
      end

      @bus.publish("/global/test", "test")
      wait_for(1000) { data }

      data.must_equal "test"
    end

    it "can subscribe to channel" do
      data = nil
      @bus.subscribe("/global/test") do |message|
        data = message.data
      end

      @bus.publish("/global/test", "test")
      wait_for(1000) { data }

      data.must_equal "test"
    end

    it "should exception if publishing restricted messages to user" do
      assert_raises(MessageBus::InvalidMessage) do
        @bus.publish("/global/test", "test", user_ids: [1])
      end
    end

    it "should exception if publishing restricted messages to group" do
      assert_raises(MessageBus::InvalidMessage) do
        @bus.publish("/global/test", "test", user_ids: [1])
      end
    end

    it "should raise if we publish to an empty group or user list" do
      assert_raises(MessageBus::InvalidMessageTarget) do
        @bus.publish "/foo", "bar", user_ids: []
      end

      assert_raises(MessageBus::InvalidMessageTarget) do
        @bus.publish "/foo", "bar", group_ids: []
      end

      assert_raises(MessageBus::InvalidMessageTarget) do
        @bus.publish "/foo", "bar", client_ids: []
      end

      assert_raises(MessageBus::InvalidMessageTarget) do
        @bus.publish "/foo", "bar", group_ids: [], user_ids: [1]
      end

      assert_raises(MessageBus::InvalidMessageTarget) do
        @bus.publish "/foo", "bar", group_ids: [1], user_ids: []
      end
    end
  end

  it "should support forking properly" do
    test_never :memory

    data = []
    @bus.subscribe do |msg|
      data << msg.data
    end

    @bus.publish("/hello", "pre-fork")
    wait_for(2000) { data.length == 1 }

    if child = Process.fork
      # The child was forked and we received its PID

      # Wait for fork to finish so we're asserting that we can still publish after it has
      Process.wait(child)

      @bus.publish("/hello", "continuation")
    else
      begin
        @bus.after_fork
        GC.start
        @bus.publish("/hello", "from-fork")
      ensure
        exit!(0)
      end
    end

    wait_for(2000) { data.length == 3 }

    @bus.publish("/hello", "after-fork")

    wait_for(2000) { data.length == 4 }

    data.must_equal(["pre-fork", "from-fork", "continuation", "after-fork"])
  end

  describe '#register_client_message_filter' do
    it 'should register the message filter correctly' do
      @bus.register_client_message_filter('/test')

      @bus.client_message_filters.must_equal([])

      @bus.register_client_message_filter('/test') { puts "hello world" }

      channel, blk = @bus.client_message_filters[0]

      blk.must_respond_to(:call)
      channel.must_equal('/test')
    end
  end

  describe "keepalive reconnect watchdog" do
    def fast_keepalive
      0.5
    end

    before do
      @original_min_keepalive = MessageBus::Implementation::MIN_KEEPALIVE
      MessageBus::Implementation.send(:remove_const, :MIN_KEEPALIVE)
      MessageBus::Implementation.const_set(:MIN_KEEPALIVE, 0)

      @log_output = StringIO.new
      @bus.configure(keepalive_interval: fast_keepalive, logger: Logger.new(@log_output))
    end

    after do
      MessageBus::Implementation.send(:remove_const, :MIN_KEEPALIVE)
      MessageBus::Implementation.const_set(:MIN_KEEPALIVE, @original_min_keepalive)
    end

    def stall_global_subscribe(backend)
      backend.define_singleton_method(:global_subscribe) do |_last_id = nil, &_blk|
        @subscribed = true
        sleep(0.001) while @subscribed
      end
    end

    it "invokes request_reconnect and logs a warning when subscriber reads stall" do
      backend = @bus.backend_instance
      reconnect_calls = 0
      stall_global_subscribe(backend)

      backend.define_singleton_method(:request_reconnect) do
        reconnect_calls += 1
        @subscribed = false
      end

      @bus.after_fork
      wait_for(1000) { @bus.listening? }

      wait_for(4000) { reconnect_calls == 1 }
      wait_for(4000) { @log_output.string.include?("no longer functioning correctly") }

      reconnect_calls.must_equal 1
      @log_output.string.must_include "timed out"
      @log_output.string.must_include "no longer functioning correctly"
    end

    it "resets @last_message so reconnect attempts are not immediate cascades" do
      backend = @bus.backend_instance
      reconnect_times = []
      stall_global_subscribe(backend)

      backend.define_singleton_method(:request_reconnect) do
        reconnect_times << Process.clock_gettime(Process::CLOCK_MONOTONIC)
      end

      @bus.after_fork
      wait_for(1000) { @bus.listening? }
      wait_for(7000) { reconnect_times.length >= 2 }

      first_gap = reconnect_times[1] - reconnect_times[0]
      first_gap.must_be :>=, fast_keepalive * 2.8
    end

    it "stays armed and tries again when request_reconnect raises" do
      backend = @bus.backend_instance
      reconnect_calls = 0
      stall_global_subscribe(backend)

      backend.define_singleton_method(:request_reconnect) do
        reconnect_calls += 1
        raise IOError, "simulated connection error"
      end

      @bus.after_fork
      wait_for(1000) { @bus.listening? }

      wait_for(8000) { reconnect_calls >= 2 }

      reconnect_calls.must_be :>=, 2
      @log_output.string.must_include "Failed to request subscriber reconnect"
      @log_output.string.must_include "simulated connection error"
    end

    it "stays armed when the keepalive publish raises" do
      backend = @bus.backend_instance
      publish_calls = 0
      real_publish = backend.method(:publish)
      stall_global_subscribe(backend)

      backend.define_singleton_method(:publish) do |*args, &blk|
        publish_calls += 1
        raise IOError, "simulated publish failure" if publish_calls == 1

        real_publish.call(*args, &blk)
      end

      @bus.after_fork
      wait_for(1000) { @bus.listening? }
      wait_for(5000) { publish_calls >= 3 }

      publish_calls.must_be :>=, 3
      @log_output.string.must_include "simulated publish failure"
    end
  end
end

